INSERT OR REPLACE INTO clunk_asset_reviews (id, workspace_id, asset_id, visual_runtime, player_facing, human_decision, note, evidence_json, reviewer_user_id) VALUES ('review-vs-village-well', 'ws-artemis-store', 'asset-vs-village-well', 'PASS', 'NOT_EVALUATED', 'PASS', '마을 광장 키트 — 형상 감사·6각도 대조표·로컬/원격 MCP 검사 통과', '{"source":"village-square","build":"examples/generated/kits/village-square/build.mjs","measuredBy":"outputs/kits/village-square/build-report.json","geometryAudit":"scripts/asset-geometry-audit.mjs — 이상 없음","visualSweep":"outputs/visual-sweep/village-well.png","mcpLocal":"tmp/kits/village-square/qa/village-well.json","mcpRemote":"https://clunk.games/api/mcp clunk_asset_validate"}', 'usr-artemis-store');
INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-vs-village-well', 'ws-artemis-store', 'asset-vs-village-well', 'village-well', '도르래 손잡이가 도는 돌우물', '돌을 세 켜 쌓아 올린 마을 우물입니다. 1.88 × 2.68 × 1.45 m 이고 난간 위까지 0.79 m 라, 사람이 기대설 수 있는 실제 우물 높이입니다. 테두리 돌은 하나하나 쐐기꼴로 깎여 안쪽 면과 바깥쪽 면이 각각 원을 이루므로 이음매에 틈이 없습니다. 물은 두께 50 mm 짜리 원반이고 난간에서 480 mm 아래에 있어, 위에서 내려다보는 시점에서 수면이 보입니다. 도르래 축은 winch_pivot 노드에 걸려 있고 "winch-crank" 동작 3.6초가 파일에 들어 있습니다 — 손잡이를 돌리면 통과 밧줄이 같이 돕니다. 두레박은 밧줄에 매달지 않고 난간에 얹어 두었습니다. 밧줄에 매달면 도르래가 돌 때 두레박이 따라 움직여야 하는데, 그렇게 만들어 두지 않았기 때문입니다. 폴리곤 1,692개, 재질 9개, 텍스처 없음.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
