INSERT OR REPLACE INTO clunk_asset_reviews (id, workspace_id, asset_id, visual_runtime, player_facing, human_decision, note, evidence_json, reviewer_user_id) VALUES ('review-vs-village-bench', 'ws-artemis-store', 'asset-vs-village-bench', 'PASS', 'NOT_EVALUATED', 'PASS', '마을 광장 키트 — 형상 감사·6각도 대조표·로컬/원격 MCP 검사 통과', '{"source":"village-square","build":"examples/generated/kits/village-square/build.mjs","measuredBy":"outputs/kits/village-square/build-report.json","geometryAudit":"scripts/asset-geometry-audit.mjs — 이상 없음","visualSweep":"outputs/visual-sweep/village-bench.png","mcpLocal":"tmp/kits/village-square/qa/village-bench.json","mcpRemote":"https://clunk.games/api/mcp clunk_asset_validate"}', 'usr-artemis-store');
INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-vs-village-bench', 'ws-artemis-store', 'asset-vs-village-bench', 'village-bench', '돌 다리를 댄 나무 벤치', '양끝을 돌로 세우고 좌판과 등받이를 나무로 짠 벤치입니다. 1.64 × 0.92 × 0.57 m, 앉는 높이 0.45 m 입니다. 좌판은 널 네 장이고 널마다 8 mm 모따기가 들어가 있어, 평면 셰이딩에서도 널 사이의 그림자 선이 남습니다. 등받이는 8도 뒤로 누워 있고, 좌판에 3.5 mm 박힌 볼트 머리 여덟 개가 위로 8.5 mm 나와 있습니다. 폴리곤 544개, 재질 6개, 텍스처 없음.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
