INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-vs-village-lamp-post', 'ws-artemis-store', 'asset-vs-village-lamp-post', 'village-lamp-post', '기름등을 단 주철 가로등', '돌 주춧돌 위에 주철 기둥을 세우고 네모난 등을 얹은 가로등입니다. 전체 0.41 × 3.06 × 0.38 m 로, 실제 가로등 높이입니다. 등피 네 장은 두께 20 mm 짜리 판이고 투명 재질을 쓰지 않았습니다 — 알파를 무시하는 엔진에서도 같은 모양으로 보입니다. 기둥에는 사다리를 거는 가로대가 한쪽에 달려 있어, 실루엣이 좌우 대칭이 아닙니다. 폴리곤 412개, 재질 5개, 텍스처 없음.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
