INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-vs-village-signpost', 'ws-artemis-store', 'asset-vs-village-signpost', 'village-signpost', '팻말 세 장을 단 방향 표지목', '팻말 세 장이 서로 다른 쪽을 가리키는 표지목입니다. 기둥은 2.10 m 이고 팻말은 1.40 m · 1.64 m · 1.88 m 높이에 각각 0°, 126°, 229° 로 달려 있어 어느 각도에서 보아도 두 장이 겹쳐 보이지 않습니다. 팻말은 끝이 뾰족한 다섯 각 단면을 35 mm 두께로 뽑은 것이라 뾰족한 끝에도 두께가 있습니다. 기둥 밑동은 돌 여덟 개로 둘러 두었습니다. 전체 크기 1.23 × 2.24 × 1.17 m, 폴리곤 444개, 재질 5개, 텍스처 없음.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
