INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-vs-village-fountain', 'ws-artemis-store', 'asset-vs-village-fountain', 'village-fountain', '가운데 기둥이 선 돌 분수', '지름 2.05 m 짜리 둥근 돌 수반에 기둥과 윗대야를 얹은 분수입니다. 테두리까지 0.58 m 라 걸터앉을 수 있는 높이입니다. 아래 수면은 두께 120 mm 짜리 고리 모양이고 윗대야의 수면은 두께 60 mm 짜리 원반입니다 — 둘 다 판이 아니라 부피가 있어 옆에서 보아도 사라지지 않습니다. 아래 수면을 고리로 만든 것은 가운데 기둥이 그 자리를 지나기 때문입니다. 놋쇠 주둥이 네 개가 사방에 달려 있습니다. 폴리곤 1,816개, 재질 5개, 텍스처 없음.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
