INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-vs-village-postbox', 'ws-artemis-store', 'asset-vs-village-postbox', 'village-postbox', '기둥에 단 쇠 우편함', '나무 기둥 위에 쇠 상자를 올린 우편함입니다. 0.42 × 1.69 × 0.34 m 이고 투입구는 1.31 m 높이에 있습니다. 투입구는 뚫린 구멍이 아니라, 20 mm 나온 놋쇠 테두리 안에 어두운 판을 앉혀 만든 것입니다 — 상자 안이 비치지 않고 뒷면 렌더에 기대지 않습니다. 상자 아래는 쇠 받침판이 받치고 있고 뚜껑은 박공 지붕 모양입니다. 폴리곤 444개, 재질 6개, 텍스처 없음.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
