INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-vs-village-noticeboard', 'ws-artemis-store', 'asset-vs-village-noticeboard', 'village-noticeboard', '종이를 붙인 마을 게시판', '기둥 두 개에 판을 끼우고 차양을 씌운 게시판입니다. 1.44 × 1.94 × 0.36 m 이고 판은 1.144 × 0.86 m, 아랫변이 0.90 m 높이에 있습니다. 붙어 있는 종이 다섯 장은 두께 6 mm 짜리 판이고 저마다 조금씩 기울어져 있으며, 각각 압정 하나로 고정돼 있습니다 — 두께 0 인 판은 이 키트에 하나도 없습니다. 폴리곤 420개, 재질 6개, 텍스처 없음.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
