INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-vs-village-path-straight', 'ws-artemis-store', 'asset-vs-village-path-straight', 'village-path-straight', '돌길 타일 (직선)', '1.000 × 1.000 m, 높이 0.062 m 짜리 돌길 한 칸입니다. 128 mm 짜리 사각돌을 길을 가로지르는 방향으로 엇갈려 깔았습니다. 모서리 타일·교차로 타일과 바닥판 크기와 높이가 같아, 어느 변끼리 붙여도 턱이 지지 않습니다. 돌마다 높이가 2 mm 안쪽에서 다르고 밝기가 세 단계로 나뉘어 있어, 여러 장을 이어 깔아도 같은 무늬가 반복되어 보이지 않습니다. 폴리곤 636개, 재질 3개, 텍스처 없음.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
