INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-vs-village-path-crossing', 'ws-artemis-store', 'asset-vs-village-path-crossing', 'village-path-crossing', '돌길 타일 (교차로)', '1.000 × 1.000 m, 높이 0.062 m 짜리 돌길 한 칸으로, 네 갈래가 만나는 자리입니다. 한쪽 방향으로 켜를 깔 수 없는 자리라 가운데를 중심으로 사각 고리를 돌려 깔고 한가운데에 마감돌을 하나 놓았습니다. 직선 타일·모서리 타일과 바닥판 크기와 높이가 같습니다. 폴리곤 456개, 재질 3개, 텍스처 없음.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
