INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-vs-village-wall-straight', 'ws-artemis-store', 'asset-vs-village-wall-straight', 'village-wall-straight', '낮은 돌담 (직선 한 칸)', '길이 1.000 m, 두께 0.300 m, 갓돌 위까지 0.550 m 짜리 돌담 한 칸입니다. 걸터앉을 수 있는 높이입니다. 앞뒤 두 겹으로 쌓았고 두 겹의 세로 이음매를 어긋나게 두었기 때문에, 이음매 자리에 담을 관통하는 구멍이 없습니다. 돌 사이는 벌어져 있지 않고 돌마다 들어간 12 mm 모따기 두 개가 만나 24 mm 홈이 됩니다. 모서리 칸과 두께·높이가 같아 x = ±0.500 에서 그대로 이어집니다. 갓돌은 양쪽으로 20 mm 씩 나와 전체 폭이 0.34 m 입니다. 폴리곤 924개, 재질 3개, 텍스처 없음.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
