INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-vs-village-wall-corner', 'ws-artemis-store', 'asset-vs-village-wall-corner', 'village-wall-corner', '낮은 돌담 (모서리)', '돌담이 직각으로 꺾이는 칸입니다. 두 팔이 각각 x = +0.500 과 z = −0.500 에서 끝나므로 직선 칸을 양쪽에 그대로 붙일 수 있고, 모서리 칸 넷과 직선 칸 넷이면 한 변 2 m 짜리 네모가 닫힙니다. 모서리에는 담 두께를 다 쓰는 귀돌을 켜마다 하나씩 따로 놓았습니다 — 두 팔을 서로 밀어 넣지 않았으므로 겹치는 자리가 없습니다. 이 부품의 원점은 바운딩 박스 가운데가 아니라 귀돌 가운데입니다. 담을 이어 붙일 때 기준이 되는 자리가 거기이기 때문입니다. 전체 0.67 × 0.55 × 0.67 m, 폴리곤 1,260개, 재질 3개, 텍스처 없음.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
