INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-vs-village-bell-tower', 'ws-artemis-store', 'asset-vs-village-bell-tower', 'village-bell-tower', '종이 흔들리는 작은 종탑', '돌 기단 위에 나무 기둥 넷을 세우고 종을 매단 종탑입니다. 1.40 × 3.09 × 1.40 m 이고 종을 매단 축은 2.30 m 높이에 있습니다. bell_pivot 노드를 돌리면 종이 흔들리고, "bell-swing" 동작 2.7초가 파일에 들어 있습니다. 흔들림은 ±16도까지입니다 — 종 아가리가 축에서 0.672 m 아래에 반지름 0.220 m 이므로 그 이상 흔들면 기둥 안쪽 면(0.405 m)에 닿습니다. 밧줄은 종에 매지 않고 기단 위에 감아 두었습니다. 종에 매면 흔들릴 때마다 밧줄이 늘어나야 하기 때문입니다. 폴리곤 1,028개, 재질 9개, 텍스처 없음.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
