INSERT OR REPLACE INTO clunk_marketplace_listings (id, workspace_id, asset_id, slug, title, description, price_cents, currency, license_status, status, published_at) VALUES ('listing-vs-kit-village-square', 'ws-artemis-store', 'asset-vs-kit-village-square', 'kit-village-square', '마을 광장 키트 (부품 15종)', '우물·벤치·가로등·표지목·분수·화분 두 종·우편함·게시판·돌길 타일 세 종·돌담 두 종·종탑, 모두 15종이 한 파일에 들어 있습니다. 부품마다 원본 파일 이름을 딴 노드 아래에 놓여 있고 서로 0.55 m 씩 떨어져 있으며, 전부 y = 0 바닥에 서 있습니다. 전체 8.56 × 3.09 × 5.61 m, 폴리곤 12,880개, 재질 12개, 텍스처 없음. 돌우물의 도르래와 종탑의 종, 두 가지 동작이 이 파일 안에 그대로 들어 있습니다. 열두 색 한 벌을 열다섯 부품이 나눠 쓰고, 그중 목재·기와·쇠·놋쇠는 코지 팜 세트와 같은 값이라 두 세트를 한 장면에 섞어 놓을 수 있습니다. 돌길 타일 세 종은 1.000 m 각 · 높이 0.062 m 로 서로 같고, 돌담 두 종은 두께 0.300 m · 높이 0.550 m 로 서로 같습니다.', 0, 'KRW', 'cleared', 'PUBLISHED', CURRENT_TIMESTAMP);
